def alien_order(words):
    adj = {ch: set() for w in words for ch in w}
    for a, b in zip(words, words[1:]):
        for x, y in zip(a, b):
            if x != y:
                adj[x].add(y)
                break
        else:
            if len(a) > len(b):
                return ""                            # prefix after its extension
    color, out = {}, []

    def dfs(u):
        color[u] = 1
        for v in adj[u]:
            if color.get(v) == 1 or (v not in color and not dfs(v)):
                return False
        color[u] = 2
        out.append(u)
        return True

    for ch in adj:
        if ch not in color and not dfs(ch):
            return ""
    return "".join(reversed(out))

def alien_order(words):
    adj = {ch: set() for w in words for ch in w}
    indeg = {ch: 0 for ch in adj}
    for a, b in zip(words, words[1:]):
        for x, y in zip(a, b):
            if x != y:
                if y not in adj[x]:
                    adj[x].add(y)
                    indeg[y] += 1
                break
        else:
            if len(a) > len(b):
                return ""
    queue = deque(ch for ch in adj if indeg[ch] == 0)
    out = []
    while queue:
        u = queue.popleft()
        out.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                queue.append(v)
    return "".join(out) if len(out) == len(adj) else ""
